(()=>{'use strict';
const words={boundary:['虛構決賽投票演練；不是正式比賽。測試影片不可播放，憑證不代表已核定的真人驗證政策。正式投票與收款未開放。','Fictional final ballot rehearsal, not an official contest. Placeholder videos cannot play. Credentials do not establish an approved real-person policy. No official voting or payment.','काल्पनिक फाइनल मतदान अभ्यास। नमुना भिडियो चल्दैन। परिचयपत्रले स्वीकृत वास्तविक व्यक्ति नीति प्रमाणित गर्दैन। आधिकारिक मतदान वा भुक्तानी खुलेको छैन।'],title:['決賽投票演練','Final ballot rehearsal','फाइनल मतदान अभ्यास'],admin:['投票管理演練','Ballot administration rehearsal','मतदान व्यवस्थापन अभ्यास'],open:['開啟十分鐘演練','Open ten-minute TEST window','दस मिनेट परीक्षण खोल्नुहोस्'],close:['關閉投票','Close voting','मतदान बन्द गर्नुहोस्'],freeze:['凍結已查核結果（51/49）','Freeze checked result (51/49)','जाँचिएको नतिजा स्थिर गर्नुहोस् (५१/४९)'],ready:['確認十位虛構影片就緒','Confirm ten placeholder videos ready','दस नमुना भिडियो तयार पुष्टि'],initialize:['建立十位虛構決賽選手','Create ten fictional finalists','दस काल्पनिक फाइनलिस्ट बनाउनुहोस्'],reload:['重新讀取','Reload','फेरि पढ्नुहोस्'],credential:['演練投票憑證','TEST voter credential','परीक्षण मतदाता परिचयपत्र'],vote:['確認投給此選手','Confirm ballot for this finalist','यो फाइनलिस्टलाई मत पुष्टि'],check:['查核我的投票收據','Check my ballot receipt','मेरो मतदान रसिद जाँच्नुहोस्'],saved:['已從資料庫確認投票收據','Ballot receipt confirmed by database','डाटाबेसबाट मतदान रसिद पुष्टि'],unknown:['結果尚未確認，請先查核投票收據，不要重複投票。','Outcome unknown. Check your receipt before retrying.','नतिजा निश्चित छैन। फेरि मत दिनुअघि रसिद जाँच्नुहोस्।'],retry:['尚無投票紀錄；可保留同一請求編號重試。','No saved ballot yet; retry keeps the same request ID.','मतदान विवरण छैन; उही अनुरोध नम्बर राखेर फेरि प्रयास गर्न सकिन्छ।'],waiting:['處理中…','Processing…','प्रक्रियामा…'],failed:['操作未完成，請重新讀取核對。','Not completed. Reload and check.','कार्य पूरा भएन। फेरि पढेर जाँच्नुहोस्।'],choose:['選擇此選手','Choose finalist','फाइनलिस्ट रोज्नुहोस्'],back:['返回選手名單','Back to finalists','फाइनलिस्ट सूचीमा फर्कनुहोस्'],human:['請完成本次真人驗證','Complete human verification for this ballot','यो मतका लागि मानव प्रमाणीकरण पूरा गर्नुहोस्'],unavailable:['目前未開放投票','Voting is not open','मतदान खुलेको छैन'],issue:['核發虛構憑證','Issue fictional credential','काल्पनिक परिचयपत्र जारी गर्नुहोस्'],person:['虛構獨立身分代號（TEST-person-…）','Independent fictional identity (TEST-person-…)','छुट्टै काल्पनिक पहिचान (TEST-person-…)'],issued:['憑證僅此次顯示；遺失時須人工處理，不可另造同一人的資格。','Credential shown once. A lost credential needs review; do not invent another identity for the same person.','परिचयपत्र एकपटक देखाइन्छ। हराएमा समीक्षा चाहिन्छ; एउटै व्यक्तिको अर्को पहिचान नबनाउनुहोस्।'],decide:['記錄票據審查','Record ballot review','मतपत्र समीक्षा सुरक्षित गर्नुहोस्'],invalidate:['作廢','Invalidate','अमान्य'],reinstate:['恢復有效','Reinstate','फेरि मान्य'],revoke:['撤銷資格','Revoke eligibility','योग्यता रद्द'],consent:['我確認這是經獨立核對的虛構測試身分，並非把Email當作唯一真人。','I confirm an independently checked fictional identity, not Email as proof of a unique person.','यो छुट्टै जाँचिएको काल्पनिक पहिचान हो; इमेललाई एक व्यक्तिको प्रमाण मानेको होइन।'],result:['凍結結果（僅測試）','Frozen result (TEST only)','स्थिर नतिजा (परीक्षण मात्र)']};
let lang='zh',state=null,selected=null,busy=false,token='',draft='',pending=null,issuePending=null,issueToken='',widget=null,confirmed=false,issuerIdentity=null;const admin=document.body.dataset.mode==='organizer';
const $=id=>document.getElementById(id),t=key=>words[key]?.[['zh','en','ne'].indexOf(lang)]||key,n=(tag,text)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;return e},button=(key,fn)=>{const e=n('button',t(key));e.type='button';e.onclick=fn;return e};
function message(key){$('feedback').textContent=t(key)}
async function api(body){const response=await fetch('/api/vote-test',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(18000)});const value=await response.json();if(!response.ok||!value.ok){const error=Error(value.error||'unavailable');error.code=value.error;throw error;}if(admin&&body.operation==='read'){const current=value.actor?.id||null;if(issuerIdentity&&issuerIdentity!==current){issuePending=null;issueToken=''}issuerIdentity=current}return value}
async function refresh(){try{state=await api({operation:'read'});render()}catch(e){state=null;render();message('failed')}}
async function command(body){if(busy)return;busy=true;render();message('waiting');try{const value=await api({version:state?.version,request_id:crypto.randomUUID(),...body});if(!value.audit_id)throw Error();await refresh();return value}catch(error){if(body.operation==='issue'&&/^(already_issued|fictional_person_required|organizer_only|invalid_request_id)$/.test(error.code||''))issuePending=null;message('failed')}finally{busy=false;render()}}
function render(){if(widget!==null&&window.turnstile){try{window.turnstile.remove(widget)}catch{}widget=null}document.documentElement.lang={zh:'zh-Hant',en:'en',ne:'ne'}[lang];$('boundary').textContent=t('boundary');const root=$('workspace');root.replaceChildren(n('h1',t(admin?'admin':'title')),button('reload',refresh));if(admin)return renderAdmin(root);if(!state)return;root.append(n('p',state.state));if(state.state!=='open')root.append(n('p',t('unavailable')));
 const candidate=state.candidates.find(c=>c.public_id===selected);if(!candidate){const list=n('div');list.className='list';for(const c of state.candidates){const b=button('choose',()=>{selected=c.public_id;history.pushState({candidate:selected},'');render()});b.className='row';b.replaceChildren(n('span',c.public_name+' · '+c.public_id));list.append(b)}root.append(list);return}
 root.append(button('back',()=>{selected=null;render()}),n('h2',candidate.public_name+' · '+candidate.public_id));const link=n('a','TEST video');link.href=candidate.video_url;link.target='_blank';link.rel='noopener noreferrer';root.append(link);
 const form=n('form'),label=n('label',t('credential')),input=n('input');input.type='password';input.autocomplete='off';input.required=true;input.value=draft;input.minLength=96;input.maxLength=96;input.oninput=()=>{draft=input.value;confirmed=false;submit.disabled=busy||Boolean(pending)||state.state!=='open'};label.append(input);form.append(label);
 const human=n('div');human.id='vote-human';form.append(n('p',t('human')),human);const submit=n('button',t('vote'));submit.type='submit';submit.className='primary';submit.disabled=busy||confirmed||Boolean(pending)||state.state!=='open';form.append(submit,button('check',checkReceipt));form.onsubmit=e=>{e.preventDefault();cast()};root.append(form);
 token='';const mount=()=>{if(document.getElementById('vote-human')!==human||!window.turnstile)return;widget=window.turnstile.render(human,{sitekey:state.turnstile_site_key,action:'ghv_final_vote',callback:value=>{if(document.getElementById('vote-human')===human)token=value},'expired-callback':()=>token='','error-callback':()=>{token='';message('human')}})};if(window.turnstile)mount();else{window.voteWidgetReady=mount;if(!document.querySelector('script[data-widget]')){const script=n('script');script.src='https://challenges.cloudflare.com/turnstile/v0/api.js?onload=voteWidgetReady&render=explicit';script.dataset.widget='true';document.head.append(script)}}

}
async function cast(){if(busy||pending)return;if(!token)return message('human');const body={operation:'cast',candidate_id:selected,credential:draft,request_id:crypto.randomUUID()};pending=body;await send(body)}
const noWrite=error=>/^(invalid_credential|ineligible|human_verification_required|invalid_ballot|invalid_candidate|voting_closed|vote_not_configured|already_voted)$/.test(error?.code||'');
async function send(body){pending=body;busy=true;const proof=token;render();message('waiting');try{const value=await api({...body,turnstile_token:proof});if(!value.receipt)throw Error();const stored=await api({operation:'receipt',credential:body.credential});if(stored.receipt!==value.receipt||stored.candidate_id!==body.candidate_id)throw Error();pending=null;confirmed=true;message('saved')}catch(error){if(noWrite(error)){pending=null;message(error.code==='human_verification_required'?'human':'failed')}else message('unknown')}finally{busy=false;render()}}
async function checkReceipt(){if(busy)return;busy=true;message('waiting');try{const value=await api({operation:'receipt',credential:pending?.credential||draft});if(value.receipt){if(pending&&value.candidate_id!==pending.candidate_id)throw Error();selected=value.candidate_id;pending=null;confirmed=true;message('saved')}else{message('retry');if(pending){const old=pending;const proof=token;if(!proof){pending=old;message('human');return}busy=false;await send(old)}}}catch(error){if(noWrite(error)){pending=null;message('failed')}else message('unknown')}finally{busy=false;render()}}
function renderAdmin(root){if(!state){root.append(button('initialize',()=>command({operation:'initialize'})));return}if(!Object.hasOwn(state,'ballots'))return root.append(n('p',t('unavailable')));root.append(n('p',state.state+' · '+state.candidates.length+' · '+state.validBallots));
 if(state.state==='draft')root.append(button('ready',()=>command({operation:'ready'})),button('open',()=>command({operation:'open',opens_at:Math.floor(Date.now()/1000)-1,closes_at:Math.floor(Date.now()/1000)+600})));
 if(state.state==='open')root.append(button('close',()=>command({operation:'close'})));if(state.state==='closed')root.append(button('freeze',()=>command({operation:'freeze'})));
 const form=n('form'),label=n('label',t('person')),person=n('input');person.required=true;person.value=issuePending?.person_key||'';person.disabled=Boolean(issuePending);person.pattern='TEST-person-[a-zA-Z0-9_-]+';label.append(person);const confirmation=n('label'),check=n('input');check.type='checkbox';check.required=true;confirmation.append(check,n('span',t('consent')));const submit=n('button',t('issue'));submit.type='submit';const output=n('input');output.type='password';output.readOnly=true;output.value=issueToken;output.setAttribute('aria-label',t('credential'));form.append(label,confirmation,submit,n('p',t('issued')),output);form.onsubmit=async e=>{e.preventDefault();issuePending=issuePending||{operation:'issue',person_key:person.value,request_id:crypto.randomUUID()};const result=await command(issuePending);if(result){issueToken=result.credential;issuePending=null;render()}};root.append(form);
 if(state.ballots.length){const review=n('form'),receipt=n('select'),verdict=n('select');for(const b of state.ballots)receipt.append(new Option(b.candidate_id+' · '+b.receipt,b.receipt));for(const value of ['invalidate','reinstate'])verdict.append(new Option(t(value),value));const submit=n('button',t('decide'));submit.type='submit';review.append(receipt,verdict,submit);review.onsubmit=e=>{e.preventDefault();command({operation:'decide',receipt:receipt.value,verdict:verdict.value,reason:'evidence_review'})};root.append(review)}
 if(state.eligibilities?.some(e=>!e.revoked)){const form=n('form'),eligible=n('select');for(const row of state.eligibilities.filter(e=>!e.revoked))eligible.append(new Option(row.id,row.id));const submit=n('button',t('revoke'));submit.type='submit';form.append(eligible,submit);form.onsubmit=e=>{e.preventDefault();command({operation:'revoke',eligibility_id:eligible.value,reason:'evidence_review'})};root.append(form)}
 if(state.result){root.append(n('h2',t('result')));for(const row of state.result.rows)root.append(n('p',row.id.slice(-6)+' · '+row.votes+' · '+row.total_score))}
 root.querySelectorAll('button,input,select').forEach(e=>e.disabled=e.disabled||busy||state.state==='frozen');
}
window.addEventListener('popstate',e=>{selected=e.state?.candidate||null;render()});document.querySelectorAll('[data-lang]').forEach(b=>b.onclick=()=>{lang=b.dataset.lang;render()});refresh();
})();
